events.command:
/bin/bash -lc "Rscript - <<'RS'
for (f in Sys.glob('inputs/*.rds')) {
  x <- readRDS(f); m <- attr(x,'metadata')
  cat('FILE',basename(f),'\\n')
  for (i in seq_along(m)) {
    cat('M',i,'TYPE',typeof(m[[i]]),'LEN',length(m[[i]]),'NAMES',paste(names(m[[i]]),collapse='|'),'\\n')
    if (is.atomic(m[[i]])) cat(paste(as.character(m[[i]]), collapse=' | '),'\\n')
  }
}
RS"
